import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.net.IDN;
import java.text.Normalizer.Form;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

// Go 版の nameprep_table.go を、Java 版が使う JDK の IDN.toASCII の nameprep のデータから作る。
// 使い方(Java 21。JDK の中の部品を読むため、次の --add-opens が要る):
//   java --add-opens java.base/java.net=ALL-UNNAMED --add-opens java.base/jdk.internal.icu.text=ALL-UNNAMED \
//        --add-opens java.base/jdk.internal.icu.lang=ALL-UNNAMED --add-opens java.base/sun.text=ALL-UNNAMED \
//        Gen.java > nameprep_table.go
public class Gen {
    static Object sp;
    static Method getCodePointValue, getValues, mapM, iterOf, normalize, ccc, direction;
    static Constructor<?> valuesCtor;
    static Field typeF;
    static int UNICODE_3_2 = 32;

    public static void main(String[] args) throws Exception {
        IDN.toASCII("a");
        Field f = IDN.class.getDeclaredField("namePrep");
        f.setAccessible(true);
        sp = f.get(null);
        Class<?> spc = sp.getClass();
        getCodePointValue = spc.getDeclaredMethod("getCodePointValue", int.class);
        getCodePointValue.setAccessible(true);
        Class<?> vc = Class.forName("jdk.internal.icu.text.StringPrep$Values");
        getValues = spc.getDeclaredMethod("getValues", char.class, vc);
        getValues.setAccessible(true);
        valuesCtor = vc.getDeclaredConstructor();
        valuesCtor.setAccessible(true);
        typeF = vc.getDeclaredField("type");
        typeF.setAccessible(true);
        Class<?> itc = Class.forName("jdk.internal.icu.text.UCharacterIterator");
        mapM = spc.getDeclaredMethod("map", itc, int.class);
        mapM.setAccessible(true);
        iterOf = itc.getDeclaredMethod("getInstance", String.class);
        iterOf.setAccessible(true);
        Class<?> nc = Class.forName("sun.text.Normalizer");
        normalize = nc.getDeclaredMethod("normalize", CharSequence.class, Form.class, int.class);
        normalize.setAccessible(true);
        ccc = nc.getDeclaredMethod("getCombiningClass", int.class);
        ccc.setAccessible(true);
        Class<?> uc = Class.forName("jdk.internal.icu.lang.UCharacter");
        direction = uc.getDeclaredMethod("getDirection", int.class);
        direction.setAccessible(true);

        List<int[]> unassigned = new ArrayList<>(), prohibited = new ArrayList<>(), randal = new ArrayList<>(), ltr = new ArrayList<>();
        List<int[]> classes = new ArrayList<>();
        Map<Integer, String> decomp = new TreeMap<>();
        Map<Long, Integer> compose = new TreeMap<>();
        int maxDecomp = 0;
        for (int cp = 0; cp <= 0xFFFF; cp++) {
            if (cp >= 0xD800 && cp <= 0xDFFF) {
                continue;
            }
            int type = type(cp);
            if (type == 0) {
                add(unassigned, cp);
            }
            if (type == 2) {
                add(prohibited, cp);
            }
            int dir = (int) direction.invoke(null, cp);
            if (dir == 1 || dir == 13) {
                add(randal, cp);
            }
            if (dir == 0) {
                add(ltr, cp);
            }
            int cls = (int) ccc.invoke(null, cp);
            if (cls != 0) {
                addClass(classes, cp, cls);
            }
            if (type == 0 || (cp >= 0xAC00 && cp <= 0xD7A3)) {
                continue;
            }
            String s = new String(Character.toChars(cp));
            String mapped = map(s);
            String d = norm(mapped, Form.NFKD);
            if (!d.equals(s)) {
                decomp.put(cp, d);
                maxDecomp = Math.max(maxDecomp, d.length());
            }
            String nfd = norm(s, Form.NFD);
            if (!nfd.equals(s) && norm(nfd, Form.NFC).equals(s)) {
                int last = nfd.codePointBefore(nfd.length());
                String prefix = norm(nfd.substring(0, nfd.length() - Character.charCount(last)), Form.NFC);
                if (prefix.codePointCount(0, prefix.length()) != 1) {
                    throw new IllegalStateException("合成の前の部分が1文字でない: " + Integer.toHexString(cp));
                }
                compose.put(((long) prefix.codePointAt(0) << 16) | last, cp);
            }
        }
        StringBuilder o = new StringBuilder();
        o.append("// Code generated by testdata/nameprep/Gen.java; DO NOT EDIT.\n\n");
        o.append("package auth\n\n");
        o.append("// このファイルの表は、Java 版が使う JDK 21 の java.net.IDN の nameprep(RFC 3491、Unicode 3.2)のデータを、\n");
        o.append("// 基本多言語面(U+0000 から U+FFFF)の文字ごとに読み出して作った。作り方は testdata/nameprep/Gen.java にある。\n\n");
        pairs(o, "nameprepUnassigned は、Unicode 3.2 で割り当てのない文字の範囲である(下端と上端の組の並び)", "nameprepUnassigned", unassigned);
        pairs(o, "nameprepProhibited は、nameprep が禁じる文字の範囲である", "nameprepProhibited", prohibited);
        pairs(o, "nameprepRandAL は、書く向きが右から左(R と AL)の文字の範囲である", "nameprepRandAL", randal);
        pairs(o, "nameprepL は、書く向きが左から右(L)の文字の範囲である", "nameprepL", ltr);
        o.append("// nameprepCombiningClass は、結合の種類が0でない文字の範囲と種類である(下端と上端と種類の組の並び)\n");
        o.append("var nameprepCombiningClass = []uint16{\n");
        StringBuilder line = new StringBuilder();
        int n = 0;
        for (int[] r : classes) {
            line.append(String.format("0x%04X, 0x%04X, %d, ", r[0], r[1], r[2]));
            if (++n % 6 == 0) {
                o.append("\t").append(line.toString().trim()).append("\n");
                line.setLength(0);
            }
        }
        if (line.length() > 0) {
            o.append("\t").append(line.toString().trim()).append("\n");
        }
        o.append("}\n\n");
        o.append("// nameprepDecomposition は、対応づけ(B.1 と B.2)のあとの互換の分解が元の文字と違う文字の、分解の結果である。\n");
        o.append("// ハングルの音節は、表に載せず、決まった計算で分解する\n");
        o.append("var nameprepDecomposition = map[rune]string{\n");
        line.setLength(0);
        n = 0;
        for (Map.Entry<Integer, String> e : decomp.entrySet()) {
            line.append(String.format("0x%04X: %s, ", e.getKey(), quote(e.getValue())));
            if (++n % 6 == 0) {
                o.append("\t").append(line.toString().trim()).append("\n");
                line.setLength(0);
            }
        }
        if (line.length() > 0) {
            o.append("\t").append(line.toString().trim()).append("\n");
        }
        o.append("}\n\n");
        o.append("// nameprepComposition は、正準の合成の組(前の文字と後ろの文字)と、合成した文字である。\n");
        o.append("// ハングルの音節は、表に載せず、決まった計算で合成する\n");
        o.append("var nameprepComposition = map[[2]rune]rune{\n");
        line.setLength(0);
        n = 0;
        for (Map.Entry<Long, Integer> e : compose.entrySet()) {
            line.append(String.format("{0x%04X, 0x%04X}: 0x%04X, ", e.getKey() >> 16, e.getKey() & 0xFFFF, e.getValue()));
            if (++n % 8 == 0) {
                o.append("\t").append(line.toString().trim()).append("\n");
                line.setLength(0);
            }
        }
        if (line.length() > 0) {
            o.append("\t").append(line.toString().trim()).append("\n");
        }
        o.append("}\n");
        System.out.print(o);
        System.err.printf("unassigned=%d prohibited=%d randal=%d l=%d classes=%d decomp=%d compose=%d maxDecomp=%d%n",
                unassigned.size(), prohibited.size(), randal.size(), ltr.size(), classes.size(), decomp.size(), compose.size(), maxDecomp);
    }

    static int type(int cp) throws Exception {
        char v = (char) getCodePointValue.invoke(sp, cp);
        Object vals = valuesCtor.newInstance();
        getValues.invoke(null, v, vals);
        return typeF.getInt(vals);
    }

    static String map(String s) throws Exception {
        try {
            return mapM.invoke(sp, iterOf.invoke(null, s), 0).toString();
        } catch (InvocationTargetException e) {
            throw new IllegalStateException(e.getCause());
        }
    }

    static String norm(String s, Form f) throws Exception {
        return (String) normalize.invoke(null, s, f, UNICODE_3_2);
    }

    static String quote(String s) {
        StringBuilder b = new StringBuilder("\"");
        s.codePoints().forEach(c -> {
            if (c == '"' || c == '\\') {
                b.append('\\').append((char) c);
            } else if (c >= 0x20 && c < 0x7F) {
                b.append((char) c);
            } else {
                b.append(String.format("\\u%04X", c));
            }
        });
        return b.append('"').toString();
    }

    static void add(List<int[]> r, int cp) {
        if (!r.isEmpty() && r.get(r.size() - 1)[1] == cp - 1) {
            r.get(r.size() - 1)[1] = cp;
        } else {
            r.add(new int[] { cp, cp });
        }
    }

    static void addClass(List<int[]> r, int cp, int cls) {
        if (!r.isEmpty() && r.get(r.size() - 1)[1] == cp - 1 && r.get(r.size() - 1)[2] == cls) {
            r.get(r.size() - 1)[1] = cp;
        } else {
            r.add(new int[] { cp, cp, cls });
        }
    }

    static void pairs(StringBuilder o, String doc, String name, List<int[]> r) {
        o.append("// ").append(doc).append("\n");
        o.append("var ").append(name).append(" = []uint16{\n");
        StringBuilder line = new StringBuilder();
        int n = 0;
        for (int[] x : r) {
            line.append(String.format("0x%04X, 0x%04X, ", x[0], x[1]));
            if (++n % 8 == 0) {
                o.append("\t").append(line.toString().trim()).append("\n");
                line.setLength(0);
            }
        }
        if (line.length() > 0) {
            o.append("\t").append(line.toString().trim()).append("\n");
        }
        o.append("}\n\n");
    }
}
